// isJSON — validate a JSON string (bug-fix starter)
// Source: src/lib/isJSON.js, src/lib/util/{assertString, includesArray, merge}.js (validator.js 13.15.35)
// Contract: by default accept only objects and arrays; allow_primitives also accepts null/false/true.
//      allow_any_value accepts anything parsable; a parse failure returns false.

function assertString(input) {
  if (input === undefined || input === null) throw new TypeError(`Expected a string but received a ${input}`);
  if (input.constructor.name !== 'String') throw new TypeError(`Expected a string but received a ${input.constructor.name}`);
}

function merge(obj = { }, defaults) {
  if (typeof obj !== 'object' || obj === null) {
    obj = {};
  }
  for (const key in defaults) {
    if (typeof obj[key] === 'undefined') {
      obj[key] = defaults[key];
    }
  }
  return obj;
}

// Inlined from src/lib/util/includesArray.js
const includes = (arr, val) => arr.some(arrVal => val === arrVal);

const default_json_options = {
  allow_primitives: false,
  allow_any_value: false,
};

function isJSON(str, options) {
  assertString(str);
  try {
    options = merge(options, default_json_options);
    const obj = JSON.parse(str);

    // When allow_any_value is true, accept anything that JSON.parse successfully parses
    if (options.allow_any_value) {
      return true;
    }

    let primitives = [];
    if (options.allow_primitives) {
      primitives = [null, false, true];
    }

    return includes(primitives, obj) || (typeof obj === 'object');
  } catch (e) { /* ignore */ }
  return false;
}

